ngx_getcwd(u_char *buf, size_t size)
{
    u_char   *p;
    size_t    n;
    u_short   utf16[NGX_MAX_PATH];

    n = GetCurrentDirectoryW(NGX_MAX_PATH, utf16);

    if (n == 0) {
        return 0;
    }

    if (n > NGX_MAX_PATH) {
        ngx_set_errno(ERROR_INSUFFICIENT_BUFFER);
        return 0;
    }

    p = ngx_utf16_to_utf8(buf, utf16, &size, NULL);

    if (p == NULL) {
        return 0;
    }

    if (p != buf) {
        ngx_free(p);
        ngx_set_errno(ERROR_INSUFFICIENT_BUFFER);
        return 0;
    }

    return size - 1;
}

ngx_open_dir(ngx_str_t *name, ngx_dir_t *dir)
{
    size_t      len;
    u_short    *u, *p;
    ngx_err_t   err;
    u_short     utf16[NGX_UTF16_BUFLEN];

    len = NGX_UTF16_BUFLEN - 2;
    u = ngx_utf8_to_utf16(utf16, name->data, &len, 2);

    if (u == NULL) {
        return NGX_ERROR;
    }

    if (ngx_win32_check_filename(u, len, 0) != NGX_OK) {
        goto failed;
    }

    p = &u[len - 1];

    *p++ = '/';
    *p++ = '*';
    *p = '\0';

    dir->dir = FindFirstFileW(u, &dir->finddata);

    if (dir->dir == INVALID_HANDLE_VALUE) {
        goto failed;
    }

    if (u != utf16) {
        ngx_free(u);
    }

    dir->valid_info = 1;
    dir->ready = 1;
    dir->name = NULL;
    dir->allocated = 0;

    return NGX_OK;

failed:

    if (u != utf16) {
        err = ngx_errno;
        ngx_free(u);
        ngx_set_errno(err);
    }

    return NGX_ERROR;
}

ngx_read_dir(ngx_dir_t *dir)
{
    u_char  *name;
    size_t   len, allocated;

    if (dir->ready) {
        dir->ready = 0;
        goto convert;
    }

    if (FindNextFileW(dir->dir, &dir->finddata) != 0) {
        dir->type = 1;
        goto convert;
    }

    return NGX_ERROR;

convert:

    name = dir->name;
    len = dir->allocated;

    name = ngx_utf16_to_utf8(name, dir->finddata.cFileName, &len, &allocated);

    if (name == NULL) {
        return NGX_ERROR;
    }

    if (name != dir->name) {

        if (dir->name) {
            ngx_free(dir->name);
        }

        dir->name = name;
        dir->allocated = allocated;
    }

    dir->namelen = len - 1;

    return NGX_OK;
}

ngx_close_dir(ngx_dir_t *dir)
{
    if (dir->name) {
        ngx_free(dir->name);
    }

    if (FindClose(dir->dir) == 0) {
        return NGX_ERROR;
    }

    return NGX_OK;
}

